INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(101, 'Genesis 4:21', 'Genesis', 4, 21, '&nbsp;د هغۀ ورور يوبل وو، هغه د هغو ټولو موسيقارانو پلار وو چې رباب او شپېلۍ غږوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(102, 'Genesis 4:22', 'Genesis', 4, 22, '&nbsp;د ضِله نه توبل‌قائِن پېدا شو، چې هغۀ به د پيتلو او اوسپنې نه هر قِسم آوزار جوړول. د توبل‌قائِن خور نعمه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(103, 'Genesis 4:23', 'Genesis', 4, 23, '&nbsp;لمک خپلو ښځو ته ووئيل، ”عدې او ضِلې، زما خبره واورئ، ما يو زلمے وژلے دے ځکه چې هغۀ زۀ وهلے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(104, 'Genesis 4:24', 'Genesis', 4, 24, '&nbsp;کۀ د قائِن د وژلو په بدل کښې اووۀ کسان وژلے شى، نو زما د وژلو په بدل کښې به اووۀ اويا کسان ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(105, 'Genesis 4:25', 'Genesis', 4, 25, '&nbsp;د آدم او حوا يو بل زوئ وشو. هغې وفرمائيل، ”خُدائ پاک د هابيل په ځائ ما له يو زوئ راکړے دے، هغه هابيل کوم چې قائِن وژلے وو.“ نو په هغۀ يې شيث نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(106, 'Genesis 4:26', 'Genesis', 4, 26, '&nbsp;د شيث يو زوئ وشو چې په هغۀ يې انوش نوم کېښودو. نو د دې نه پس خلقو د مالِک خُدائ نوم په عبادت کښې اخستل شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(107, 'Genesis 5:1', 'Genesis', 5, 1, '&nbsp;دا د آدم د اولاد نسب‌نامه ده. کله چې خُدائ پاک بنى آدم پېدا کړو، هغه يې د خپل ځان په شان پېدا کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(108, 'Genesis 5:2', 'Genesis', 5, 2, '&nbsp;هغوئ يې نر او ښځه پېدا کړل، بختور يې کړل او ”بنى آدم“ نوم يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(109, 'Genesis 5:3', 'Genesis', 5, 3, '&nbsp;کله چې آدم د يو سل دېرشو کالو وو، نو د هغۀ يو زوئ وشو چې د هغۀ په شان وو او شيث نوم يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(110, 'Genesis 5:4', 'Genesis', 5, 4, '&nbsp;د دې نه پس آدم اتۀ سوه کاله نور ژوندے وو. د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(111, 'Genesis 5:5', 'Genesis', 5, 5, '&nbsp;او د نهۀ سوه دېرشو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(112, 'Genesis 5:6', 'Genesis', 5, 6, '&nbsp;کله چې شيث د يو سل پينځو کالو وو، د هغۀ زوئ انوش پېدا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(113, 'Genesis 5:7', 'Genesis', 5, 7, '&nbsp;هغه نور اتۀ سوه اووۀ کاله ژوندے وو. د هغۀ نور بچى هم پېدا شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(114, 'Genesis 5:8', 'Genesis', 5, 8, '&nbsp;او د نهۀ سوه دولسو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(115, 'Genesis 5:9', 'Genesis', 5, 9, '&nbsp;کله چې انوش د لس کم سلو کالو وو، د هغۀ زوئ قېنان وشو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(116, 'Genesis 5:10', 'Genesis', 5, 10, '&nbsp;او انوش نور اتۀ سوه پينځلس کاله ژوندے وو. د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(117, 'Genesis 5:11', 'Genesis', 5, 11, '&nbsp;او د نهۀ سوه او پينځو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(118, 'Genesis 5:12', 'Genesis', 5, 12, '&nbsp;کله چې قېنان د اوياؤ کالو وو، د هغۀ يو زوئ محلل‌اېل پېدا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(119, 'Genesis 5:13', 'Genesis', 5, 13, '&nbsp;او قېنان نور اتۀ سوه څلوېښت کاله ژوندے وو. د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(120, 'Genesis 5:14', 'Genesis', 5, 14, '&nbsp;او د نهۀ سوه لسو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(121, 'Genesis 5:15', 'Genesis', 5, 15, '&nbsp;محلل‌اېل د پينځو شپېتو کالو وو، چې د هغۀ زوئ يارد پېدا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(122, 'Genesis 5:16', 'Genesis', 5, 16, '&nbsp;او هغه نور اتۀ سوه او دېرش کاله ژوندے وو. د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(123, 'Genesis 5:17', 'Genesis', 5, 17, '&nbsp;او د پينځۀ کم نهۀ سوو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(124, 'Genesis 5:18', 'Genesis', 5, 18, '&nbsp;چې کله يارد د يو سل دوه شپېتو کالو وو، د هغۀ زوئ حنوک وشو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(125, 'Genesis 5:19', 'Genesis', 5, 19, '&nbsp;او بيا نور اتۀ سوه کاله ژوندے وو. د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(126, 'Genesis 5:20', 'Genesis', 5, 20, '&nbsp;او د نهۀ سوه دوه شپېتو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(127, 'Genesis 5:21', 'Genesis', 5, 21, '&nbsp;کله چې حنوک د پينځو شپېتو کالو وو، د هغۀ زوئ مِتهوشله پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(128, 'Genesis 5:22', 'Genesis', 5, 22, '&nbsp;د دې نه پس، حنوک درې سوه کاله د خُدائ پاک په ملګرتيا کښې ژوندے وو او نور بچى يې هم پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(129, 'Genesis 5:23', 'Genesis', 5, 23, '&nbsp;د هغۀ ټول عُمر درې سوه پينځۀ شپېتۀ کاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(130, 'Genesis 5:24', 'Genesis', 5, 24, '&nbsp;حنوک خپل ژوند د خُدائ پاک په ملګرتيا کښې تېر کړو او د هغې نه پس خلقو ونۀ ليدو، ځکه چې هغه خُدائ پاک خپل ځان ته پورته اوچت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(131, 'Genesis 5:25', 'Genesis', 5, 25, '&nbsp;کله چې مِتهوشله د يو سل اووۀ اتيا کالو وو، د هغۀ زوئ لمک پېدا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(132, 'Genesis 5:26', 'Genesis', 5, 26, '&nbsp;او هغه نور اووۀ سوه او دوه اتيا کاله ژوندے وو، د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(133, 'Genesis 5:27', 'Genesis', 5, 27, '&nbsp;او د نهۀ سوه نهۀ شپېتو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(134, 'Genesis 5:28', 'Genesis', 5, 28, '&nbsp;کله چې لمک د يو سل دوه اتيا کالو وو، د هغۀ يو زوئ وشو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(135, 'Genesis 5:29', 'Genesis', 5, 29, '&nbsp;لمک ووئيل، ”دا ماشوم به مونږ له د مالِک خُدائ لعنتى کړے شوې زمکې د سختې خوارۍ نه آرام راکړى.“ نو د هغۀ نوم يې نوح کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(136, 'Genesis 5:30', 'Genesis', 5, 30, '&nbsp;لمک نور پينځۀ کم شپږ سوه کاله ژوندے وو. د هغۀ نور بچى هم پېدا شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(137, 'Genesis 5:31', 'Genesis', 5, 31, '&nbsp;او د اووۀ سوو اووۀ اوياؤ کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(138, 'Genesis 5:32', 'Genesis', 5, 32, '&nbsp;د پينځو سوو کالو عُمر نه پس د نوح درې زامن وشول، شيم، حام او يافت د دوئ نومونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(139, 'Genesis 6:1', 'Genesis', 6, 1, '&nbsp;کله چې بنى آدم په ټوله دُنيا کښې خوارۀ شول، نو د دوئ لوڼه پېدا کېدې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(140, 'Genesis 6:2', 'Genesis', 6, 2, '&nbsp;نو څۀ آسمانى مخلوق دا ښائسته پېغلې ولېدې، د خوښې پېغلې يې ترې بوتلې او وادۀ يې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(141, 'Genesis 6:3', 'Genesis', 6, 3, '&nbsp;بيا مالِک خُدائ وفرمائيل، ”زۀ به بنى آدم نۀ پرېږدم چې هغوئ دې همېشه دپاره ژوندى وى، دا فانى مخلوق دے. د نن نه پس به دوئ د شپږ شلو کالو نه زيات ژوندى نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(142, 'Genesis 6:4', 'Genesis', 6, 4, '&nbsp;په هغه ورځو کښې او هم داسې وروستو، په زمکه دېوان وُو چې هغوئ د بنيادمو د ښځو او د آسمانى مخلوق بچى وُو. هغوئ د هغه وخت تکړه او مشهور خلق وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(143, 'Genesis 6:5', 'Genesis', 6, 5, '&nbsp;چې کله مالِک خُدائ وکتل چې هر يو کس په دُنيا کښې بدعمله وو او هر وخت د دوئ خيالونه بد وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(144, 'Genesis 6:6', 'Genesis', 6, 6, '&nbsp;نو هغه په خپلو کړو پښېمانه شو چې دوئ يې پېدا کړل او په زمکه يې آباد کړل. د هغۀ زړۀ مات شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(145, 'Genesis 6:7', 'Genesis', 6, 7, '&nbsp;نو هغۀ وفرمائيل، ”زۀ به دا خلق چې ما پېدا کړى دى د زمکې د مخ نه لرې کړم او ورسره ځناور او مارغان هم، ځکه چې زۀ ډېر پښېمانه يم چې ما دوئ پېدا کړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(146, 'Genesis 6:8', 'Genesis', 6, 8, '&nbsp;خو مالِک خُدائ د نوح نه رضا وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(147, 'Genesis 6:11', 'Genesis', 6, 11, '&nbsp;خو نور ټول خلق د خُدائ پاک د سيدها لارې نه لرى وُو او هر طرف ته زور او ظلم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(148, 'Genesis 6:12', 'Genesis', 6, 12, '&nbsp;خُدائ پاک چې دُنيا وکتله نو د خلقو د بدعملۍ نه ډکه وه، ځکه چې خلق د سيدها لارې نه لرې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(149, 'Genesis 6:13', 'Genesis', 6, 13, '&nbsp;خُدائ پاک نوح ته وفرمائيل، ”ما د ټولو بنيادمو د ختمولو فېصله کړې ده. زۀ به دوئ ټول تباه کړم، ځکه چې دُنيا د دوئ د بدعملۍ نه ډکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(150, 'Genesis 6:14', 'Genesis', 6, 14, '&nbsp;د ځان دپاره د ښۀ لرګى نه يوه لويه کشتۍ جوړه کړه، کوټې په کښې جوړې کړه او دننه او بهر يې په تارکولو لېوه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(151, 'Genesis 6:15', 'Genesis', 6, 15, '&nbsp;دا کشتۍ يو سل پينځۀ څلوېښت ګزه اوږده، څليريشت ګزه پلنه او څوارلس ګزه اوچته جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(152, 'Genesis 6:16', 'Genesis', 6, 16, '&nbsp;کشتۍ له چت هم جوړ کړه او چت يې د سر نه اوولس اِنچې په ترڅ جوړ کړه. دا درې چتيزه جوړه کړه او يو طرف ته دروازه هم په کښې پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(153, 'Genesis 6:17', 'Genesis', 6, 17, '&nbsp;ګوره، زۀ به يو سېلاب راولم چې په زمکه ټول مخلوق تباه شى. هر ساه لرونکے څيز به مړ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(154, 'Genesis 6:18', 'Genesis', 6, 18, '&nbsp;خو زۀ تا سره لوظ کوم، د خپلې ښځې سره کشتۍ ته وخېژه، خپل زامن او د هغوئ ښځې هم وخېژوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(155, 'Genesis 6:21', 'Genesis', 6, 21, '&nbsp;د ځان او دوئ دپاره هر قِسم خوراک راجمع کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(156, 'Genesis 6:22', 'Genesis', 6, 22, '&nbsp;نو نوح هم هغه شان وکړل چې څنګه خُدائ پاک حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(157, 'Genesis 7:1', 'Genesis', 7, 1, '&nbsp;بيا مالِک خُدائ نوح ته وفرمائيل، ”د خپل ټول بال بچ سره کشتۍ ته وخېژه، ما ته پته ده چې يواځې تۀ په ټوله دُنيا کښې هغه صادق سړے يې چې ښۀ عمل کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(158, 'Genesis 7:2', 'Genesis', 7, 2, '&nbsp;د هر قِسم حلال ځناورو نه اووۀ جوړې واخله، خو د هر قِسم حرام ځناورو نه صِرف يوه يوه جوړه واخله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(159, 'Genesis 7:3', 'Genesis', 7, 3, '&nbsp;او هر قِسم مارغانو نه هم اووۀ جوړې واخله، د دې دپاره چې هر قِسم ځناور او مارغان په مخ د زمکې ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(160, 'Genesis 7:4', 'Genesis', 7, 4, '&nbsp;د نن نه اووۀ ورځې پس به زۀ باران راولم چې څلوېښت شپې او څلوېښت ورځې به وريږى، د دې دپاره چې ټول ژوندى د زمکې د مخ نه ورک کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
